122	/****************************************************************************
123	 * Private Functions - Clock and Reset Control
124	 ****************************************************************************/
125	
126	static void gmac_clock_enable(void)
127	{
128	  uint32_t reg;
129	
130	  /* Enable GMAC0 clocks: clk_500m_eth0 + clk_axi4_eth0 */
131	
132	  reg = getreg32(REG_CLK_EN_0);
133	  reg |= CLK_EN_ETH0_500M | CLK_EN_ETH0_AXI4;
134	  putreg32(reg, REG_CLK_EN_0);
135	
136	  /* Deassert clock-domain resets used by the CVITEK clock-reset
137	   * controller.  Do not confuse these IDs with the main reset-controller
138	   * IDs at 0x03003000.
139	   */
140	
141	  clk_reset_deassert(CLK_RST_500M_ETH0);
142	  clk_reset_deassert(CLK_RST_AXI_ETH0);
143	
144	  /* Release the main reset-controller lines for GMAC and internal EPHY.
145	   * The Linux CVITEK reset driver deasserts by setting the corresponding
146	   * bit in the reset bank.
147	   */
148	
149	  reset_assert(RST_ETH0);
150	  reset_assert(RST_ETHPHY);
151	  reset_assert(RST_ETHPHYRST_APB);
152	  up_udelay(10);
153	  reset_deassert(RST_ETHPHYRST_APB);
154	  reset_deassert(RST_ETHPHY);
155	  reset_deassert(RST_ETH0);
156	  up_udelay(10);
157	
158	  syslog(LOG_INFO, "sg2000_eth: GMAC clocks enabled, CLK_EN_0=0x%08" PRIX32
159	         " RESET0=0x%08" PRIX32 " RESET3=0x%08" PRIX32 "\n",
160	         getreg32(REG_CLK_EN_0), getreg32(REG_RESET_BANK(0)),
161	         getreg32(REG_RESET_BANK(3)));
162	}
