412	/****************************************************************************
413	 * Name: ephy_full_tuning
414	 *
415	 * Description:
416	 *   Run the full CV182XA analog tuning sequence via APB, then switch back
417	 *   to MDIO control.  Matches Linux cv182xa_phy_config_init().
418	 *   MUST be called AFTER MDIO is confirmed operational, as it accesses
419	 *   internal pages and starts auto-negotiation which can interfere with
420	 *   MDIO if run before the MDIO interface is active.
421	 *
422	 ****************************************************************************/
423	
424	static void ephy_full_tuning(uintptr_t phy_base, uintptr_t phy_top)
425	{
426	  /* ephy_full_analog_init expects APB mode; caller ensures MDIO is working
427	   * before we switch to APB for tuning.
428	   */
429	
430	  putreg32(0x0001, phy_top + 0x4);
431	  ephy_full_analog_init(phy_base, phy_top);
432	
433	  /* ephy_full_analog_init ends with:
434	   *   page 0 + autoneg start (0x090e) + force full-duplex
435	   * Switch control back to MDIO so the GMAC can manage the PHY.
436	   */
437	
438	  putreg32(0x0000, phy_top + 0x4);
439	  up_mdelay(10);
440	
441	  syslog(LOG_INFO, "sg2000_eth: EPHY full tuning done, top=0x%08" PRIX32
442	         " sel=0x%08" PRIX32 "\n",
443	         getreg32(phy_top), getreg32(phy_top + 0x4));
444	}
445	
446	/* SG2000/CV181x uses the DWMAC1000 MDIO layout at offsets 0x10/0x14
447	 * (GMAC_MII_ADDR / GMAC_MII_DATA registers of the GMAC core).
448	 */
449	
450	static uint16_t mdio_read(uintptr_t gmac_base, int phy_addr, int reg)
451	{
452	  uint32_t cmd;
453	  int timeout = 10000;
454	
455	  do
456	    {
457	      if (!(getreg32(gmac_base + GMAC_MII_ADDR) &
458	            GMAC_MII_BUSY))
459	        {
460	          break;
461	        }
462	
463	      up_udelay(1);
464	    }
465	  while (--timeout > 0);
466	
467	  if (timeout <= 0)
468	    {
469	      return 0xffff;
470	    }
471	
472	  putreg32(0, gmac_base + GMAC_MII_DATA);
473	
474	  cmd = (((uint32_t)phy_addr & 0x1f) << GMAC_MII_PHY_SHIFT) |
475	        (((uint32_t)reg & 0x1f) << GMAC_MII_REG_SHIFT) |
476	        GMAC_MII_CR_250_300M | GMAC_MII_BUSY;
477	  putreg32(cmd, gmac_base + GMAC_MII_ADDR);
478	
479	  timeout = 10000;
480	  do
481	    {
482	      if (!(getreg32(gmac_base + GMAC_MII_ADDR) &
483	            GMAC_MII_BUSY))
484	        {
485	          return getreg32(gmac_base + GMAC_MII_DATA) & 0xffff;
486	        }
487	
488	      up_udelay(1);
489	    }
490	  while (--timeout > 0);
491	
492	  return 0xffff;
493	}
494	
495	static void mdio_write(uintptr_t gmac_base, int phy_addr, int reg,
496	                       uint16_t data)
497	{
498	  uint32_t cmd;
499	  int timeout = 10000;
500	
501	  putreg32(data, gmac_base + GMAC_MII_DATA);
502	  cmd = (((uint32_t)phy_addr & 0x1f) << GMAC_MII_PHY_SHIFT) |
503	        (((uint32_t)reg & 0x1f) << GMAC_MII_REG_SHIFT) |
504	        GMAC_MII_CR_250_300M | GMAC_MII_WRITE |
505	        GMAC_MII_BUSY;
506	  putreg32(cmd, gmac_base + GMAC_MII_ADDR);
507	
508	  do
509	    {
510	      if (!(getreg32(gmac_base + GMAC_MII_ADDR) &
511	            GMAC_MII_BUSY))
512	        {
513	          break;
514	        }
515	
516	      up_udelay(1);
517	    }
518	  while (--timeout > 0);
519	}
