656	/****************************************************************************
657	 * Private Functions - DMA Descriptor Management
658	 ****************************************************************************/
659	
660	static int alloc_dma(struct sg2000_eth_priv_s *priv)
661	{
662	  int i;
663	
664	  priv->tx_desc = kmm_memalign(16, TX_RING_SIZE *
665	                                sizeof(struct sg2000_dma_desc_s));
666	  priv->rx_desc = kmm_memalign(16, RX_RING_SIZE *
667	                                sizeof(struct sg2000_dma_desc_s));
668	
669	  if (!priv->tx_desc || !priv->rx_desc)
670	    {
671	      return -ENOMEM;
672	    }
673	
674	  memset(priv->tx_desc, 0, TX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
675	  memset(priv->rx_desc, 0, RX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
676	
677	  /* For MMU-less or identity-mapped platforms, virtual address = physical.
678	   * TODO: For strict MMU kernel builds, use mm_virt_to_phys().
679	   */
680	
681	  priv->tx_desc_phys = (uint32_t)(uintptr_t)priv->tx_desc;
682	  priv->rx_desc_phys = (uint32_t)(uintptr_t)priv->rx_desc;
683	
684	  for (i = 0; i < TX_RING_SIZE; i++)
685	    {
686	      priv->tx_buf[i] = kmm_memalign(4, TX_BUF_SIZE);
687	      if (!priv->tx_buf[i])
688	        {
689	          return -ENOMEM;
690	        }
691	
692	      priv->tx_pkt[i] = NULL;
693	    }
694	
695	  for (i = 0; i < RX_RING_SIZE; i++)
696	    {
697	      priv->rx_buf[i] = kmm_memalign(4, RX_BUF_SIZE);
698	      if (!priv->rx_buf[i])
699	        {
700	          return -ENOMEM;
701	        }
702	
703	      /* Touch and clean each RX buffer's cache lines now, so there
704	       * are no dirty cache lines from previous heap use that could
705	       * later be written back and overwrite DMA-received data.
706	       */
707	
708	      memset(priv->rx_buf[i], 0, RX_BUF_SIZE);
709	    }
710	
711	  /* Flush the zeroed RX buffers to DDR.  After this, RX buffers have
712	   * clean cache lines — safe for DMA to write into without risk of
713	   * stale dirty lines being written back later.
714	   */
715	
716	  c906_clean_dcache_range((uintptr_t)priv->rx_desc,
717	                          (uintptr_t)priv->rx_desc +
718	                          RX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
719	
720	  for (i = 0; i < RX_RING_SIZE; i++)
721	    {
722	      c906_clean_dcache_range((uintptr_t)priv->rx_buf[i],
723	                              (uintptr_t)priv->rx_buf[i] + RX_BUF_SIZE);
724	    }
725	
726	  return 0;
727	}
728	
729	static void init_desc_and_dma(struct sg2000_eth_priv_s *priv)
730	{
731	  uintptr_t base = priv->gmac_base;
732	  int i;
733	
734	  /* Initialize TX descriptors.
735	   * Mark the last descriptor with END_RING so DMA knows the ring boundary.
736	   */
737	
738	  for (i = 0; i < TX_RING_SIZE; i++)
739	    {
740	      priv->tx_desc[i].des0 = 0;
741	      priv->tx_desc[i].des1 = (i == TX_RING_SIZE - 1) ? TX_DESC_TER : 0;
742	      priv->tx_desc[i].des2 = (uint32_t)(uintptr_t)priv->tx_buf[i];
743	      priv->tx_desc[i].des3 = 0;
744	      priv->tx_pkt[i] = NULL;
745	    }
746	
747	  /* Initialize RX descriptors: set OWN=1 (DMA owns them, can write).
748	   * Mark the last descriptor with RER (RX End of Ring) in des1.
749	   */
750	
751	  for (i = 0; i < RX_RING_SIZE; i++)
752	    {
753	      priv->rx_desc[i].des0 = DESC_OWN;
754	      priv->rx_desc[i].des1 = RX_BUF_SIZE |
755	                              ((i == RX_RING_SIZE - 1) ? RX_DESC_RER : 0);
756	      priv->rx_desc[i].des2 = (uint32_t)(uintptr_t)priv->rx_buf[i];
757	      priv->rx_desc[i].des3 = 0;
758	    }
759	
760	  priv->tx_cur = 0;
761	  priv->tx_dirty = 0;
762	  priv->tx_free_idx = 0;
763	  priv->tx_complete_count = 0;
764	  priv->rx_pending = false;
765	  priv->rx_cur = 0;
766	
767	  /* Flush all descriptor writes from D-cache to DDR.
768	   * Without this, DMA will read stale (zeroed) descriptor data
769	   * and immediately set TU / RU in CSR5.
770	   * Use address-range clean — only touches descriptor memory.
771	   */
772	
773	  c906_clean_dcache_range((uintptr_t)priv->tx_desc,
774	                          (uintptr_t)priv->tx_desc +
775	                          TX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
776	  c906_clean_dcache_range((uintptr_t)priv->rx_desc,
777	                          (uintptr_t)priv->rx_desc +
778	                          RX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
779	  C906_SYNC_S();
780	
781	  /* Verify descriptor size compatibility before configuring DMA Bus Mode.
782	   *
783	   * ATDS=0 uses normal 16-byte descriptors (OWN in TDES0, control bits
784	   * FS/LS/IC/TER in TDES1).  The descriptor size is always 16 bytes
785	   * regardless of the timestamp engine state, so the 32-byte extended
786	   * descriptor problem does not apply here.
787	   *
788	   * We still log HW_FEATURE for diagnostics and explicitly disable the
789	   * timestamp engine if present (timestamp is not used by this driver).
790	   */
791	  {
792	    uint32_t hw_feat = getreg32(base + DMA_HW_FEATURE);
793	
794	    syslog(LOG_INFO,
795	           "sg2000_eth: DMA_HW_FEATURE=0x%08" PRIX32 "\n", hw_feat);
796	
797	    if (hw_feat & DMA_HW_FEATURE_TSEN)
798	      {
799	        /* Timestamp engine is present — not needed, keep it off. */
800	
801	        uint32_t ts_ctrl = getreg32(base + GMAC_TIMESTAMP_CTRL);
802	
803	        if (ts_ctrl & GMAC_TS_TSENA)
804	          {
805	            putreg32(ts_ctrl & ~GMAC_TS_TSENA,
806	                     base + GMAC_TIMESTAMP_CTRL);
807	            syslog(LOG_WARNING,
808	                   "sg2000_eth: timestamp was enabled; "
809	                   "disabled (not used)\n");
810	          }
811	
812	        syslog(LOG_INFO,
813	               "sg2000_eth: timestamp HW present, TSENA=0, "
814	               "ATDS=0 (16-byte normal desc)\n");
815	      }
816	    else
817	      {
818	        syslog(LOG_INFO,
819	               "sg2000_eth: no timestamp HW, "
820	               "ATDS=0 (16-byte normal desc)\n");
821	      }
822	  }
823	
824	  /* Configure DMA Bus Mode (CSR0): Fixed Burst, AAL, USP, PBL=8 (ATDS=0) */
825	  putreg32(DMA_BUS_DEFAULT, base + DMA_BUS_MODE);
826	
827	  /* Configure AXI Bus Mode (CSR10): burst lengths + OSR limits */
828	  putreg32(DMA_AXI_DEFAULT, base + DMA_AXI_BUS_MODE);
829	
830	  /* Write descriptor ring base addresses */
831	  putreg32(priv->tx_desc_phys, base + DMA_TX_BASE_ADDR);
832	  putreg32(priv->rx_desc_phys, base + DMA_RCV_BASE_ADDR);
833	
834	  /* Mask all DMA interrupts via CSR7 (they are unmasked in start_mac_and_dma) */
835	  putreg32(0, base + DMA_INTR_ENA);
836	}
