838	/****************************************************************************
839	 * Private Functions - MAC and DMA Control
840	 ****************************************************************************/
841	
842	static void set_mac_addr(uintptr_t gmac_base, const uint8_t *mac)
843	{
844	  uint32_t hi;
845	  uint32_t lo;
846	
847	  hi = (mac[5] << 8) | mac[4] | GMAC_HI_REG_AE;
848	  lo = (mac[3] << 24) | (mac[2] << 16) | (mac[1] << 8) | mac[0];
849	
850	  putreg32(hi, gmac_base + GMAC_ADDR_HIGH(0));
851	  putreg32(lo, gmac_base + GMAC_ADDR_LOW(0));
852	}
853	
854	static void start_mac_and_dma(struct sg2000_eth_priv_s *priv)
855	{
856	  uintptr_t gmac_base = priv->gmac_base;
857	  uint32_t v;
858	
859	  /* Configure MAC based on PHY negotiation results */
860	
861	  v = GMAC_CORE_INIT;
862	  if (priv->speed == 100)
863	    {
864	      v |= GMAC_CONFIG_FES;   /* 100M */
865	    }
866	
867	  if (priv->duplex)
868	    {
869	      v |= GMAC_CONFIG_DM;    /* Full duplex */
870	    }
871	
872	  /* Enable MAC TX and RX */
873	  v |= GMAC_CONFIG_TE | GMAC_CONFIG_RE;
874	
875	  putreg32(v, gmac_base + GMAC_CONFIG);
876	
877	  /* Packet filter at correct DWMAC1000 offset (0x0004, not 0x0008).
878	   * Pass multicast + broadcast + unicast (promiscuous mode).
879	   */
880	
881	  putreg32(GMAC_FILTER_HMC | GMAC_FILTER_PM | GMAC_FILTER_PR,
882	           gmac_base + GMAC_FRAME_FILTER);
883	
884	  /* Enable MAC interrupts */
885	  putreg32(GMAC_INT_DEFAULT, gmac_base + GMAC_INT_MASK);
886	
887	  /* Enable DMA interrupts via CSR7 */
888	  putreg32(DMA_INTR_DEFAULT_MASK, gmac_base + DMA_INTR_ENA);
889	
890	  /* Start TX and RX DMA via CSR6 (single control register for DWMAC1000):
891	   * TSF (TX Store and Forward) + RSF (RX Store and Forward) +
892	   * OSF (Operate on Second Frame) + ST (Start TX) + SR (Start RX)
893	   */
894	
895	  putreg32(DMA_CONTROL_TSF | DMA_CONTROL_RSF | DMA_CONTROL_OSF |
896	           DMA_CONTROL_ST | DMA_CONTROL_SR,
897	           gmac_base + DMA_CONTROL);
898	}
