900	/****************************************************************************
901	 * Private Functions - Doorbell Helpers
902	 ****************************************************************************/
903	
904	static void tx_doorbell(struct sg2000_eth_priv_s *priv)
905	{
906	  /* DWMAC1000: write any value to DMA_XMT_POLL_DEMAND (CSR1) to trigger
907	   * the TX DMA engine to re-fetch descriptors from the TX descriptor ring.
908	   */
909	
910	  putreg32(1, priv->gmac_base + DMA_XMT_POLL_DEMAND);
911	}
912	
913	static void rx_doorbell(struct sg2000_eth_priv_s *priv)
914	{
915	  /* DWMAC1000: write any value to DMA_RCV_POLL_DEMAND (CSR2) to trigger
916	   * the RX DMA engine to re-fetch descriptors from the RX descriptor ring.
917	   */
918	
919	  putreg32(1, priv->gmac_base + DMA_RCV_POLL_DEMAND);
920	}
921	
922	/****************************************************************************
923	 * Private Functions - Hardware Transmit
924	 ****************************************************************************/
925	
926	/* Forward declaration: processes deferred work from ISR in thread context.
927	 * Called from hw_transmit() and netdriver_receive().
928	 */
929	
930	static void process_deferred_work(struct sg2000_eth_priv_s *priv);
931	
932	static int hw_transmit(struct sg2000_eth_priv_s *priv,
933	                       const uint8_t *data, int len)
934	{
935	  unsigned int idx = priv->tx_cur;
936	  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
937	  uint32_t csr5_before;
938	  uint32_t csr6;
939	
940	  /* Free any TX packets that were completed by DMA and counted by
941	   * tx_cleanup (ISR) since the last time we were here.  This must
942	   * happen in thread context — not in the ISR.
943	   */
944	
945	  process_deferred_work(priv);
946	
947	  /* Diagnostic: snapshot CSR5/CSR6 before TX submission */
948	
949	  csr5_before = getreg32(priv->gmac_base + DMA_STATUS);
950	  csr6 = getreg32(priv->gmac_base + DMA_CONTROL);
951	
952	  /* Copy data to DMA TX buffer */
953	
954	  memcpy(priv->tx_buf[idx], data, len);
955	
956	  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
957	
958	  /* Set OWN on des0.  FS | LS | IC | len on des1.
959	   * Preserve TER (END_RING) bit in des1 if it was set during init.
960	   */
961	
962	  desc->des1 = (uint32_t)len | TX_DESC_FS | TX_DESC_LS | TX_DESC_IC |
963	               (desc->des1 & TX_DESC_TER);
964	  desc->des0 = DESC_OWN;
965	
966	  /* Diagnostic: dump first 50 bytes of TX buffer (pointed to by des2) */
967	
968	  {
969	    int i;
970	    int dump_len = len < 50 ? len : 50;
971	
972	    syslog(LOG_INFO,
973	           "sg2000_eth: TX data[%u] des2=0x%08" PRIX32
974	           " first %d bytes:",
975	           idx, desc->des2, dump_len);
976	
977	    for (i = 0; i < dump_len; i += 16)
978	      {
979	        int row = 0;
980	        char hex[64];
981	        char ascii[20];
982	        int j;
983	
984	        row += snprintf(hex + row, sizeof(hex) - row, "  %04x:", i);
985	
986	        for (j = 0; j < 16; j++)
987	          {
988	            if (i + j < dump_len)
989	              {
990	                row += snprintf(hex + row, sizeof(hex) - row,
991	                                " %02x", priv->tx_buf[idx][i + j]);
992	                ascii[j] = (priv->tx_buf[idx][i + j] >= 32 &&
993	                           priv->tx_buf[idx][i + j] < 127)
994	                           ? priv->tx_buf[idx][i + j] : '.';
995	              }
996	            else
997	              {
998	                row += snprintf(hex + row, sizeof(hex) - row, "   ");
999	                ascii[j] = ' ';
1000	              }
1001	          }
1002	
1003	        ascii[16] = '\0';
1004	        syslog(LOG_INFO, "%s  |%s|\n", hex, ascii);
1005	      }
1006	  }
1007	
1008	  /* Diagnostic: dump TX descriptor and DMA state before doorbell */
1009	
1010	  syslog(LOG_INFO,
1011	         "sg2000_eth: TX idx=%u len=%d\n"
1012	         "  desc des0=0x%08" PRIX32 " des1=0x%08" PRIX32
1013	         " des2=0x%08" PRIX32 " des3=0x%08" PRIX32 "\n"
1014	         "  CSR5=0x%08" PRIX32 " CSR6=0x%08" PRIX32
1015	         " TX_BASE=0x%08" PRIX32 " RX_BASE=0x%08" PRIX32 "\n"
1016	         "  data[0..13]: %02x %02x %02x %02x %02x %02x"
1017	         " %02x %02x %02x %02x %02x %02x %02x %02x\n",
1018	         idx, len,
1019	         desc->des0, desc->des1, desc->des2, desc->des3,
1020	         csr5_before, csr6,
1021	         getreg32(priv->gmac_base + DMA_TX_BASE_ADDR),
1022	         getreg32(priv->gmac_base + DMA_RCV_BASE_ADDR),
1023	         data[0], data[1], data[2], data[3], data[4], data[5],
1024	         data[6], data[7], data[8], data[9], data[10], data[11],
1025	         data[12], data[13]);
1026	
1027	  /* Advance tx_cur so tx_cleanup (called from ISR on TX completion)
1028	   * can find this packet.  Packet is tracked in tx_pkt[idx] by the
1029	   * caller BEFORE this function is called, so the ISR can safely
1030	   * free it even if TX completes immediately.
1031	   */
1032	
1033	  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);
1034	
1035	  /* Flush D-cache to DDR so DMA can see the descriptor and buffer.
1036	   * Only clean the specific cache lines we touched (buffer + descriptor),
1037	   * NOT the entire D-cache.  This avoids disturbing other kernel state.
1038	   */
1039	
1040	  c906_dma_flush_before_tx((uintptr_t)priv->tx_buf[idx], len,
1041	                           (uintptr_t)desc,
1042	                           sizeof(struct sg2000_dma_desc_s));
1043	
1044	  /* Ring the TX doorbell and return immediately.  TX completion is
1045	   * handled by the ISR (DMA_STATUS_TI → tx_cleanup → netpkt_free →
1046	   * netdev_lower_txdone).  No polling needed.
1047	   */
1048	
1049	  tx_doorbell(priv);
1050	
1051	  return 0;
1052	}
1053	
1054	/****************************************************************************
1055	 * Private Functions - TX Cleanup (called from ISR on TX complete)
1056	 ****************************************************************************/
1057	
1058	static void tx_cleanup(struct sg2000_eth_priv_s *priv)
1059	{
1060	  /* Called from ISR context.  Only advance tx_dirty and increment the
1061	   * completion counter — do NOT free netpkts or call netdev_lower_txdone.
1062	   * Those heap operations must happen in thread context (process_tx_deferred)
1063	   * to avoid corrupting the heap when an ISR interrupts an ongoing malloc/free.
1064	   */
1065	
1066	  while (priv->tx_dirty != priv->tx_cur)
1067	    {
1068	      struct sg2000_dma_desc_s *desc = &priv->tx_desc[priv->tx_dirty];
1069	
1070	      /* Invalidate D-cache to see DMA's write-back (OWN cleared) */
1071	
1072	      C906_DCACHE_CIAL();
1073	      C906_SYNC_S();
1074	
1075	      if (desc->des0 & DESC_OWN)
1076	        {
1077	          break;
1078	        }
1079	
1080	      /* DMA completed this slot — count it but defer the free.
1081	       * The tx_pkt[] pointer is still valid; process_tx_deferred()
1082	       * will free it from thread context.
1083	       */
1084	
1085	      priv->tx_complete_count++;
1086	      priv->tx_dirty = (priv->tx_dirty + 1) & (TX_RING_SIZE - 1);
1087	    }
1088	}
1089	
1090	/****************************************************************************
1091	 * Name: process_deferred_work
1092	 *
1093	 * Description:
1094	 *   Process work items that were deferred from ISR context:
1095	 *   1. Free completed TX packets (tx_cleanup advanced tx_dirty; we free).
1096	 *   2. Signal RX ready (ISR set rx_pending; we call netdev_lower_rxready).
1097	 *
1098	 *   Must ONLY be called from thread context — never from ISR.
1099	 *
1100	 ****************************************************************************/
1101	
1102	static void process_deferred_work(struct sg2000_eth_priv_s *priv)
1103	{
1104	  /* 1. Free completed TX packets that tx_cleanup (ISR) marked as done. */
1105	
1106	  while (priv->tx_free_idx != priv->tx_dirty)
1107	    {
1108	      if (priv->tx_pkt[priv->tx_free_idx] != NULL)
1109	        {
1110	          netpkt_free(&priv->dev, priv->tx_pkt[priv->tx_free_idx],
1111	                      NETPKT_TX);
1112	          priv->tx_pkt[priv->tx_free_idx] = NULL;
1113	          netdev_lower_txdone(&priv->dev);
1114	        }
1115	
1116	      priv->tx_free_idx = (priv->tx_free_idx + 1) &
1117	                          (TX_RING_SIZE - 1);
1118	    }
1119	
1120	  /* 2. If the ISR flagged an RX frame arrival, notify the upper half.
1121	   *    netdev_lower_rxready may allocate netpkts internally, so it must
1122	   *    run in thread context, not ISR context.
1123	   */
1124	
1125	  if (priv->rx_pending)
1126	    {
1127	      priv->rx_pending = false;
1128	      netdev_lower_rxready(&priv->dev);
1129	    }
1130	}
1131	
1132	/****************************************************************************
1133	 * Private Functions - ISR
1134	 ****************************************************************************/
1135	
1136	static int sg2000_eth_isr(int irq, void *context, void *arg)
1137	{
1138	  struct sg2000_eth_priv_s *priv = (struct sg2000_eth_priv_s *)arg;
1139	  uintptr_t base = priv->gmac_base;
1140	  uint32_t status;
1141	  uint32_t mac;
1142	
1143	  /* Clear MAC interrupts */
1144	
1145	  mac = getreg32(base + GMAC_INT_STATUS);
1146	  if (mac)
1147	    {
1148	      putreg32(mac, base + GMAC_INT_STATUS);
1149	    }
1150	
1151	  /* Read DMA Status (CSR5 at 0x1014) */
1152	
1153	  status = getreg32(base + DMA_STATUS);
1154	
1155	  if (!status)
1156	    {
1157	      return OK;
1158	    }
1159	
1160	  /* Write-1-to-clear the status bits (CSR5 bits 0-16 are W1C) */
1161	
1162	  putreg32(status & DMA_STATUS_W1C_MASK, base + DMA_STATUS);
1163	
1164	  if (status & DMA_STATUS_NIS)
1165	    {
1166	      /* Normal interrupt.
1167	       * IMPORTANT: do NOT call syslog or any heap-allocating function
1168	       * from ISR context — the network thread may be mid-malloc when
1169	       * we preempt it, corrupting the heap.
1170	       */
1171	
1172	      if (status & DMA_STATUS_RI)
1173	        {
1174	          /* Defer RX notification to thread context.
1175	           * Just set a flag; process_deferred_work() will call
1176	           * netdev_lower_rxready() from safe thread context.
1177	           */
1178	
1179	          priv->rx_pending = true;
1180	        }
1181	
1182	      if (status & DMA_STATUS_TI)
1183	        {
1184	          /* TX complete: only advances tx_dirty + counts.
1185	           * Actual netpkt_free happens later in thread context
1186	           * via process_deferred_work().
1187	           */
1188	
1189	          tx_cleanup(priv);
1190	        }
1191	    }
1192	
1193	  if (status & DMA_STATUS_AIS)
1194	    {
1195	      /* Abnormal interrupt — no logging in ISR context.
1196	       * The upper half will detect problems via link status
1197	       * or TX/RX timeouts.
1198	       */
1199	    }
1200	
1201	  return OK;
1202	}
1203	
1204	/****************************************************************************
1205	 * Name: sg2000_eth_tx_test
1206	 *
1207	 * Description:
1208	 *   Minimal hardware TX verification test.
1209	 *   Bypasses the network stack — directly programs a TX descriptor,
1210	 *   rings the doorbell, and verifies the DMA engine can:
1211	 *     Layer 1: Fetch the descriptor from DDR  (OWN bit cleared)
1212	 *     Layer 2: Read buffer data correctly     (no Underflow)
1213	 *     Layer 3: Generate TX Complete interrupt  (CSR5 TI bit)
1214	 *
1215	 *   Prerequisite: ifup has completed (PHY up, DMA running).
1216	 *
1217	 ****************************************************************************/
1218	
1219	static int sg2000_eth_tx_test(void)
1220	{
1221	  FAR struct sg2000_eth_priv_s *priv = &g_eth_priv;
1222	  unsigned int idx = priv->tx_cur;
1223	  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
1224	  uint32_t csr5_before;
1225	  uint32_t csr5_after;
1226	  uint32_t csr6;
1227	  int timeout;
1228	  int test_len = 64;
1229	  int ret = 0;
1230	
1231	  /* STEP 0: Pre-flight checks */
1232	
1233	  if (!priv->link_up)
1234	    {
1235	      syslog(LOG_ERR, "tx_test: PHY link down, cannot test\n");
1236	      return -ENETDOWN;
1237	    }
1238	
1239	  if (desc->des0 & DESC_OWN)
1240	    {
1241	      syslog(LOG_ERR, "tx_test: desc[%u] OWN=1, ring busy\n", idx);
1242	      return -EBUSY;
1243	    }
1244	
1245	  syslog(LOG_INFO,
1246	         "=== sg2000_eth TX hardware test ===\n"
1247	         "  tx_desc[%u]=%p  tx_buf=%p  test_len=%d\n",
1248	         idx, desc, priv->tx_buf[idx], test_len);
1249	
1250	  /* STEP 1: Build a minimal broadcast ARP frame.
1251	   * dst=ff:ff:ff:ff:ff:ff  src=our MAC  type=0x0806  payload=0xAA
1252	   */
1253	
1254	  memset(priv->tx_buf[idx], 0, test_len);
1255	  memset(priv->tx_buf[idx], 0xff, 6);
1256	  memcpy(priv->tx_buf[idx] + 6, priv->mac_addr, 6);
1257	  priv->tx_buf[idx][12] = 0x08;
1258	  priv->tx_buf[idx][13] = 0x06;
1259	  memset(priv->tx_buf[idx] + 14, 0xaa, test_len - 14);
1260	
1261	  /* STEP 2: Snapshot hardware state before submission */
1262	
1263	  csr5_before = getreg32(priv->gmac_base + DMA_STATUS);
1264	  csr6 = getreg32(priv->gmac_base + DMA_CONTROL);
1265	
1266	  syslog(LOG_INFO,
1267	         "tx_test: BEFORE doorbell\n"
1268	         "  desc des0=0x%08" PRIX32 " des2=0x%08" PRIX32 "\n"
1269	         "  CSR5=0x%08" PRIX32 " CSR6=0x%08" PRIX32
1270	         " TX_FSM=%u\n",
1271	         desc->des0, desc->des2, csr5_before, csr6,
1272	         (csr5_before >> 20) & 0x7);
1273	
1274	  /* Clear stale TI / TU / ETI from CSR5 so the test starts clean.
1275	   * These bits may have been set during DMA init (TU fires when DMA
1276	   * finds all TX descriptors with OWN=0).  Without clearing, the
1277	   * polling loop would see a stale TI and report false success.
1278	   */
1279	
1280	  {
1281	    uint32_t csr5_clear = DMA_STATUS_TI | DMA_STATUS_TU |
1282	                          DMA_STATUS_UNF | DMA_STATUS_TPS |
1283	                          DMA_STATUS_TJT;
1284	    putreg32(csr5_clear, priv->gmac_base + DMA_STATUS);
1285	  }
1286	
1287	  /* Flush the CSR5 write to device before proceeding.
1288	   * DMA_STATUS is a device register — need fence to ensure the
1289	   * clear is visible before the descriptor OWN=1 is visible.
1290	   */
1291	
1292	  __asm__ volatile ("fence w,o" ::: "memory");
1293	
1294	  /* STEP 3: Program TX descriptor.
1295	   *   des2 = buffer physical address
1296	   *   des1 = len | FS | LS | IC (preserve TER)
1297	   *   des0 = OWN (hand to DMA)
1298	   */
1299	
1300	  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
1301	  desc->des1 = (uint32_t)test_len | TX_DESC_FS | TX_DESC_LS |
1302	               TX_DESC_IC | (desc->des1 & TX_DESC_TER);
1303	  desc->des0 = DESC_OWN;
1304	
1305	  /* STEP 4: Advance tx_cur BEFORE ringing the doorbell, mirroring
1306	   * hw_transmit.  This lets tx_cleanup (ISR) process this slot and
1307	   * increment tx_complete_count when DMA finishes.
1308	   */
1309	
1310	  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);
1311	  priv->tx_pkt[idx] = NULL;
1312	
1313	  /* Snapshot the completion counter so we can verify the ISR ran */
1314	
1315	  {
1316	    int complete_snapshot = priv->tx_complete_count;
1317	
1318	    /* Flush only the buffer + descriptor cache lines */
1319	
1320	    c906_dma_flush_before_tx((uintptr_t)priv->tx_buf[idx], test_len,
1321	                             (uintptr_t)desc,
1322	                             sizeof(struct sg2000_dma_desc_s));
1323	
1324	    syslog(LOG_INFO, "tx_test: D-cache flushed (range), "
1325	           "ringing TX doorbell...\n");
1326	
1327	    /* STEP 5: Ring TX doorbell */
1328	
1329	    tx_doorbell(priv);
1330	
1331	    /* STEP 6: Poll OWN only.  Do NOT poll CSR5 TI — the ISR races
1332	     * with us and clears TI before we can read it.
1333	     */
1334	
1335	    timeout = 50000;
1336	    csr5_after = 0;
1337	
1338	    while (--timeout > 0)
1339	      {
1340	        C906_DCACHE_CIAL();
1341	        C906_SYNC_S();
1342	
1343	        csr5_after = getreg32(priv->gmac_base + DMA_STATUS);
1344	
1345	        if (!(desc->des0 & DESC_OWN))
1346	          {
1347	            break;
1348	          }
1349	
1350	        up_udelay(10);
1351	      }
1352	
1353	    /* STEP 7: Wait a bit for the ISR to run and increment the
1354	     * completion counter, then verify layer by layer.
1355	     */
1356	
1357	    if (timeout > 0)
1358	      {
1359	        int isr_wait;
1360	
1361	        for (isr_wait = 0; isr_wait < 10000; isr_wait++)
1362	          {
1363	            if (priv->tx_complete_count != complete_snapshot)
1364	              {
1365	                break;
1366	              }
1367	
1368	            up_udelay(10);
1369	          }
1370	      }
1371	
1372	    syslog(LOG_INFO,
1373	           "tx_test: waited %d us  timeout=%s\n"
1374	           "  CSR5=0x%08" PRIX32 " TI=%s  tx_complete=%d (was %d)\n",
1375	           (50000 - timeout) * 10,
1376	           timeout > 0 ? "no" : "YES",
1377	           csr5_after,
1378	           (csr5_after & DMA_STATUS_TI) ? "SET" : "clear",
1379	           priv->tx_complete_count, complete_snapshot);
1380	
1381	    /* Layer 1: Did DMA clear OWN? */
1382	
1383	    if (desc->des0 & DESC_OWN)
1384	      {
1385	        syslog(LOG_ERR,
1386	               "*** FAIL [L1]: OWN still set — DMA did NOT fetch "
1387	               "descriptor!\n"
1388	               "  CSR5=0x%08" PRIX32 " TX_FSM=%u\n",
1389	               csr5_after, (csr5_after >> 20) & 0x7);
1390	        ret = -ETIMEDOUT;
1391	        goto out;
1392	      }
1393	
1394	    syslog(LOG_INFO,
1395	           "  [L1 PASS] DMA fetched descriptor (OWN cleared)\n");
1396	
1397	    /* Layer 2: Underflow / error check */
1398	
1399	    if (csr5_after & DMA_STATUS_UNF)
1400	      {
1401	        syslog(LOG_ERR,
1402	               "*** FAIL [L2]: TX Underflow — DMA could not read "
1403	               "buffer data!\n  CSR5=0x%08" PRIX32 "\n",
1404	               csr5_after);
1405	        ret = -EIO;
1406	        goto out;
1407	      }
1408	
1409	    if (desc->des0 & TX_DESC_ES)
1410	      {
1411	        syslog(LOG_ERR,
1412	               "*** FAIL [L2]: TX Error Summary in des0=0x%08"
1413	               PRIX32 "\n", desc->des0);
1414	        ret = -EIO;
1415	        goto out;
1416	      }
1417	
1418	    syslog(LOG_INFO,
1419	           "  [L2 PASS] No Underflow/Error — data read OK\n");
1420	
1421	    /* Layer 3: Did the TX complete ISR fire?
1422	     * We check tx_complete_count instead of CSR5 TI because the
1423	     * ISR clears TI (W1C) before we can poll it.
1424	     */
1425	
1426	    if (priv->tx_complete_count == complete_snapshot)
1427	      {
1428	        syslog(LOG_ERR,
1429	               "*** FAIL [L3]: ISR did NOT process TX completion "
1430	               "(tx_complete_count unchanged at %d)\n"
1431	               "  Check IRQ routing / CSR7 / GMAC_INT_MASK.\n",
1432	               complete_snapshot);
1433	        ret = -EIO;
1434	        goto out;
1435	      }
1436	
1437	    syslog(LOG_INFO,
1438	           "  [L3 PASS] ISR processed TX (tx_complete_count "
1439	           "%d → %d)\n",
1440	           complete_snapshot, priv->tx_complete_count);
1441	
1442	    syslog(LOG_INFO,
1443	           "=== TX TEST PASSED ===  total ~%d us\n",
1444	           (50000 - timeout) * 10);
1445	  }
1446	
1447	out:
1448	  /* tx_cur was already advanced before the doorbell (see STEP 4).
1449	   * Just clear any lingering interrupt bits so the test doesn't
1450	   * leave side effects for the normal TX path.
1451	   */
1452	
1453	  if (csr5_after & DMA_STATUS_TI)
1454	    {
1455	      putreg32(DMA_STATUS_TI, priv->gmac_base + DMA_STATUS);
1456	    }
1457	
1458	  return ret;
1459	}
1460	
1461	/****************************************************************************
1462	 * Name: netdriver_ifup
1463	 *
1464	 * Description:
1465	 *   OpenVela netdev_ops_s ifup callback.  Starts the network device.
1466	 *
1467	 ****************************************************************************/
1468	
1469	static int netdriver_ifup(FAR struct netdev_lowerhalf_s *dev)
1470	{
1471	  FAR struct sg2000_eth_priv_s *priv =
1472	      (FAR struct sg2000_eth_priv_s *)dev;
1473	  int ret;
1474	
1475	  syslog(LOG_INFO, "sg2000_eth: ifup begin\n");
1476	
1477	  /* Ensure GMAC clocks and resets are configured */
1478	
1479	  gmac_clock_enable();
1480	
1481	  /* Set MAC core init (includes PS=MII mode) before PHY/MDIO operations. */
1482	
1483	  putreg32(GMAC_CORE_INIT, priv->gmac_base + GMAC_CONFIG);
1484	
1485	  ephy_hardware_reset(priv->phy_base, priv->phy_top);
1486	  up_mdelay(10);
1487	
1488	  ret = mdio_verify_phy(priv->gmac_base);
1489	  if (ret < 0)
1490	    {
1491	      nerr("ERROR: MDIO PHY not responding: %d\n", ret);
1492	      return ret;
1493	    }
1494	
1495	  syslog(LOG_INFO, "sg2000_eth: MDIO operational "
1496	         "mdio_addr=0x%08" PRIX32 " mdio_data=0x%08" PRIX32 "\n",
1497	         getreg32(priv->gmac_base + GMAC_MII_ADDR),
1498	         getreg32(priv->gmac_base + GMAC_MII_DATA));
1499	
1500	  ephy_full_tuning(priv->phy_base, priv->phy_top);
1501	
1502	  ret = phy_config_init(priv);
1503	  if (ret < 0)
1504	    {
1505	      nerr("ERROR: PHY init failed: %d\n", ret);
1506	      return ret;
1507	    }
1508	
1509	  ret = dma_soft_reset(priv->gmac_base);
1510	  if (ret < 0)
1511	    {
1512	      syslog(LOG_ERR, "sg2000_eth: DMA reset failed after PHY/MDIO "
1513	             "diagnostics: %d\n", ret);
1514	      return ret;
1515	    }
1516	
1517	  if (priv->tx_desc == NULL || priv->rx_desc == NULL)
1518	    {
1519	      ret = alloc_dma(priv);
1520	      if (ret < 0)
1521	        {
1522	          nerr("ERROR: alloc_dma failed: %d\n", ret);
1523	          return ret;
1524	        }
1525	    }
1526	
1527	  init_desc_and_dma(priv);
1528	  set_mac_addr(priv->gmac_base, priv->mac_addr);
1529	  start_mac_and_dma(priv);
1530	  rx_doorbell(priv);
1531	
1532	  /* Diagnostic: verify DMA state machines after initialization.
1533	   * TS[22:20]=TX state, RS[19:17]=RX state.  Both should show Running.
1534	   */
1535	
1536	  {
1537	    uint32_t csr5 = getreg32(priv->gmac_base + DMA_STATUS);
1538	    uint32_t csr6 = getreg32(priv->gmac_base + DMA_CONTROL);
1539	    unsigned int tx_state = (csr5 >> 20) & 0x7;
1540	    unsigned int rx_state = (csr5 >> 17) & 0x7;
1541	    static const char * const states[] = {
1542	      "Stopped", "Running(FetchDesc)", "Running(WaitEnd)",
1543	      "Running(ReadData/RxWait)", "Suspended(RxUnavail)",
1544	      "Running(CloseDesc)", "Running(FlushRx)", "Running(QueueRx)"
1545	    };
1546	
1547	    syslog(LOG_INFO,
1548	           "sg2000_eth: DMA state CSR5=0x%08" PRIX32
1549	           " CSR6=0x%08" PRIX32 "\n"
1550	           "  TX_FSM=%u(%s) RX_FSM=%u(%s)\n"
1551	           "  TX_DESC[0]=0x%08" PRIX32 " RX_DESC[0]=0x%08" PRIX32 "\n",
1552	           csr5, csr6,
1553	           tx_state, states[tx_state],
1554	           rx_state, states[rx_state],
1555	           priv->tx_desc[0].des0, priv->rx_desc[0].des0);
1556	  }
1557	
1558	  up_enable_irq(priv->irq);
1559	  netdev_lower_carrier_on(dev);
1560	
1561	  syslog(LOG_INFO, "sg2000_eth: ifup done, %d Mbps %s duplex\n",
1562	         priv->speed, priv->duplex ? "Full" : "Half");
1563	
1564	  /* Run minimal HW TX verification before returning to upper half */
1565	
1566	  sg2000_eth_tx_test();
1567	
1568	  return OK;
1569	}
1570	
1571	/****************************************************************************
1572	 * Name: netdriver_ifdown
1573	 *
1574	 * Description:
1575	 *   OpenVela netdev_ops_s ifdown callback.  Stops the network device.
1576	 *
1577	 ****************************************************************************/
1578	
1579	static int netdriver_ifdown(FAR struct netdev_lowerhalf_s *dev)
1580	{
1581	  FAR struct sg2000_eth_priv_s *priv =
1582	      (FAR struct sg2000_eth_priv_s *)dev;
1583	  uint32_t v;
1584	
1585	  up_disable_irq(priv->irq);
1586	
1587	  /* Stop TX and RX DMA via CSR6 (DMA_CONTROL at 0x1018).
1588	   * Clear ST (bit 13) and SR (bit 1).
1589	   */
1590	
1591	  v = getreg32(priv->gmac_base + DMA_CONTROL);
1592	  putreg32(v & ~(DMA_CONTROL_ST | DMA_CONTROL_SR),
1593	           priv->gmac_base + DMA_CONTROL);
1594	
1595	  /* Disable MAC TX/RX */
1596	
1597	  v = getreg32(priv->gmac_base + GMAC_CONFIG);
1598	  putreg32(v & ~(GMAC_CONFIG_TE | GMAC_CONFIG_RE),
1599	           priv->gmac_base + GMAC_CONFIG);
1600	
1601	  netdev_lower_carrier_off(dev);
1602	
1603	  ninfo("netdriver_ifdown: interface down\n");
1604	
1605	  return OK;
1606	}
1607	
1608	/****************************************************************************
1609	 * Name: netdriver_transmit
1610	 *
1611	 * Description:
1612	 *   OpenVela netdev_ops_s transmit callback.  Sends a packet.
1613	 *   The driver takes ownership of the netpkt and MUST free it after TX
1614	 *   completion (or on error).
1615	 *
1616	 *   Returned Value:
1617	 *     OK on success (pkt queued for TX); negated errno on failure.
1618	 *
1619	 ****************************************************************************/
1620	
1621	static int netdriver_transmit(FAR struct netdev_lowerhalf_s *dev,
1622	                               FAR netpkt_t *pkt)
1623	{
1624	  FAR struct sg2000_eth_priv_s *priv =
1625	      (FAR struct sg2000_eth_priv_s *)dev;
1626	  unsigned int len = netpkt_getdatalen(dev, pkt);
1627	  uint8_t *tmp_buf = NULL;
1628	  const uint8_t *data;
1629	  int ret;
1630	
1631	  if (len > SG2000_ETH_BUFSIZE)
1632	    {
1633	      nerr("ERROR: TX packet too large: %u\n", len);
1634	      netpkt_free(dev, pkt, NETPKT_TX);
1635	      return -E2BIG;
1636	    }
1637	
1638	  /* Extract data from netpkt.  If fragmented, copy out to a heap buffer;
1639	   * otherwise use the IOB data pointer directly.
1640	   *
1641	   * A heap buffer is used instead of a stack buffer because
1642	   * SG2000_ETH_BUFSIZE (1600 bytes) risks stack overflow on the
1643	   * netdev thread which has a limited stack size.
1644	   */
1645	
1646	  if (netpkt_is_fragmented(pkt))
1647	    {
1648	      tmp_buf = kmm_malloc(SG2000_ETH_BUFSIZE);
1649	      if (!tmp_buf)
1650	        {
1651	          nerr("ERROR: kmm_malloc(%u) for TX copy buffer failed\n",
1652	               SG2000_ETH_BUFSIZE);
1653	          netpkt_free(dev, pkt, NETPKT_TX);
1654	          return -ENOMEM;
1655	        }
1656	
1657	      syslog(LOG_INFO,
1658	             "sg2000_eth: TX fragmented pkt, len=%u, "
1659	             "copied to heap buf=%p\n", len, tmp_buf);
1660	
1661	      netpkt_copyout(dev, tmp_buf, pkt, len, 0);
1662	      data = tmp_buf;
1663	    }
1664	  else
1665	    {
1666	      data = netpkt_getdata(dev, pkt);
1667	      if (!data)
1668	        {
1669	          nerr("ERROR: netpkt_getdata returned NULL\n");
1670	          netpkt_free(dev, pkt, NETPKT_TX);
1671	          return -EINVAL;
1672	        }
1673	    }
1674	
1675	  /* Check if TX ring is full before proceeding */
1676	
1677	  {
1678	    unsigned int idx = priv->tx_cur;
1679	
1680	    if (priv->tx_desc[idx].des0 & DESC_OWN)
1681	      {
1682	        if (tmp_buf)
1683	          {
1684	            kmm_free(tmp_buf);
1685	          }
1686	
1687	        return -EBUSY;
1688	      }
1689	
1690	    /* Track this packet BEFORE calling hw_transmit.  TX completion
1691	     * is interrupt-driven — the ISR may fire immediately after the
1692	     * doorbell and must find the packet in tx_pkt[idx].
1693	     */
1694	
1695	    priv->tx_pkt[idx] = pkt;
1696	  }
1697	
1698	  /* Send via DMA (interrupt-driven, returns immediately) */
1699	
1700	  ret = hw_transmit(priv, data, len);
1701	
1702	  /* Free the temporary copy buffer if it was allocated.
1703	   * Safe to free here: hw_transmit() already memcpy'd data into the
1704	   * DMA TX buffer, which is independent of the source buffer.
1705	   */
1706	
1707	  if (tmp_buf)
1708	    {
1709	      kmm_free(tmp_buf);
1710	    }
1711	
1712	  if (ret < 0)
1713	    {
1714	      nerr("ERROR: hw_transmit failed: %d\n", ret);
1715	
1716	      /* Clear the tracking slot on failure */
1717	      {
1718	        irqstate_t flags = up_irq_save();
1719	        unsigned int slot = (priv->tx_cur - 1) & (TX_RING_SIZE - 1);
1720	
1721	        priv->tx_pkt[slot] = NULL;
1722	        up_irq_restore(flags);
1723	      }
1724	
1725	      netpkt_free(dev, pkt, NETPKT_TX);
1726	      return ret;
1727	    }
1728	
1729	  return OK;
1730	}
1731	
1732	/****************************************************************************
1733	 * Name: netdriver_receive
1734	 *
1735	 * Description:
1736	 *   OpenVela netdev_ops_s receive callback.  Called by upper half when
1737	 *   netdev_lower_rxready() was signaled.  Returns one received packet, or
1738	 *   NULL if no more packets are available.
1739	 *
1740	 *   Returned Value:
1741	 *     A netpkt_t * containing the received packet, or NULL.
1742	 *
1743	 ****************************************************************************/
1744	
1745	static FAR netpkt_t *netdriver_receive(FAR struct netdev_lowerhalf_s *dev)
1746	{
1747	  FAR struct sg2000_eth_priv_s *priv =
1748	      (FAR struct sg2000_eth_priv_s *)dev;
1749	  FAR netpkt_t *pkt = NULL;
1750	  struct sg2000_dma_desc_s *desc;
1751	  uint32_t status;
1752	  int frame_len;
1753	  int ret;
1754	
1755	  /* Free any TX packets completed since the last RX poll.
1756	   * Safe here because netdriver_receive runs in thread context.
1757	   */
1758	
1759	  process_deferred_work(priv);
1760	
1761	  /* Check if there is a completed RX descriptor.
1762	   * CIAL: write back any dirty cache lines, then invalidate all.
1763	   * This ensures we see DMA's write-back (OWN=0, frame length, etc.)
1764	   * rather than stale cached data.
1765	   */
1766	
1767	  desc = &priv->rx_desc[priv->rx_cur];
1768	  C906_DCACHE_CIAL();
1769	  C906_SYNC_S();
1770	
1771	  if (desc->des0 & DESC_OWN)
1772	    {
1773	      /* DMA still owns it — no packet ready.
1774	       * This can happen if rxready was signaled spuriously or for
1775	       * a previous packet already consumed.
1776	       */
1777	
1778	      syslog(LOG_INFO,
1779	             "sg2000_eth: RX OWN still set  rx_cur=%u des0=0x%08"
1780	             PRIX32 "\n", priv->rx_cur, desc->des0);
1781	
1782	      return NULL;
1783	    }
1784	
1785	  status = desc->des0;
1786	
1787	  syslog(LOG_INFO,
1788	         "sg2000_eth: RX frame  rx_cur=%u des0=0x%08" PRIX32
1789	         " FL=%u\n", priv->rx_cur, status,
1790	         ((status >> RX_DESC_FL_SHIFT) & RX_DESC_FL_MASK));
1791	
1792	  /* Check for errors */
1793	
1794	  if (status & RX_DESC_ES)
1795	    {
1796	      nerr("ERROR: RX error, status=0x%08" PRIX32 "\n", status);
1797	      goto refill;
1798	    }
1799	
1800	  /* Get frame length.  GMAC_CONFIG_ACS is set, so the hardware
1801	   * already strips the FCS; the length from the descriptor is the
1802	   * actual frame length without CRC.
1803	   */
1804	
1805	  frame_len = ((status >> RX_DESC_FL_SHIFT) & RX_DESC_FL_MASK);
1806	
1807	  if (frame_len <= 0 || frame_len > CONFIG_NET_ETH_PKTSIZE)
1808	    {
1809	      nwarn("WARNING: Invalid RX frame length: %d\n", frame_len);
1810	      goto refill;
1811	    }
1812	
1813	  /* Allocate a netpkt for the received data */
1814	
1815	  pkt = netpkt_alloc(dev, NETPKT_RX);
1816	  if (!pkt)
1817	    {
1818	      nerr("ERROR: netpkt_alloc failed\n");
1819	      goto refill;
1820	    }
1821	
1822	  /* Copy data from DMA RX buffer into the netpkt.
1823	   * CIAL above already invalidated cache, so we read fresh
1824	   * DMA-written data from DDR.
1825	   */
1826	
1827	  ret = netpkt_copyin(dev, pkt, priv->rx_buf[priv->rx_cur], frame_len, 0);
1828	  if (ret < 0)
1829	    {
1830	      nerr("ERROR: netpkt_copyin failed: %d\n", ret);
1831	      netpkt_free(dev, pkt, NETPKT_RX);
1832	      pkt = NULL;
1833	      goto refill;
1834	    }
1835	
1836	  syslog(LOG_INFO,
1837	         "sg2000_eth: RX pkt OK  len=%d  first bytes: "
1838	         "%02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x %02x\n",
1839	         frame_len,
1840	         priv->rx_buf[priv->rx_cur][0], priv->rx_buf[priv->rx_cur][1],
1841	         priv->rx_buf[priv->rx_cur][2], priv->rx_buf[priv->rx_cur][3],
1842	         priv->rx_buf[priv->rx_cur][4], priv->rx_buf[priv->rx_cur][5],
1843	         priv->rx_buf[priv->rx_cur][6], priv->rx_buf[priv->rx_cur][7],
1844	         priv->rx_buf[priv->rx_cur][8], priv->rx_buf[priv->rx_cur][9],
1845	         priv->rx_buf[priv->rx_cur][10], priv->rx_buf[priv->rx_cur][11]);
1846	
1847	refill:
1848	  /* Return the descriptor to DMA (set OWN=1).
1849	   * Preserve RER (RX End of Ring) bit in des1 if set during init.
1850	   * Clean only this descriptor's cache line — no need to flush
1851	   * the entire cache.
1852	   */
1853	
1854	  desc->des0 = DESC_OWN;
1855	  desc->des1 = RX_BUF_SIZE | (desc->des1 & RX_DESC_RER);
1856	
1857	  c906_clean_dcache_range((uintptr_t)desc,
1858	                          (uintptr_t)desc +
1859	                          sizeof(struct sg2000_dma_desc_s));
1860	  C906_SYNC_S();
1861	  C906_DMA_FENCE();
1862	
1863	  priv->rx_cur = (priv->rx_cur + 1) & (RX_RING_SIZE - 1);
1864	  rx_doorbell(priv);
1865	
1866	  return pkt;
1867	}
