1891	/****************************************************************************
1892	 * Name: sg2000_eth_initialize
1893	 *
1894	 * Description:
1895	 *   Initialize the SG2000 Ethernet driver and register it with the OpenVela
1896	 *   network stack as a netdev_lowerhalf_s device.
1897	 *
1898	 *   Called from board_late_initialize() during system bringup.
1899	 *
1900	 ****************************************************************************/
1901	
1902	int sg2000_eth_initialize(void)
1903	{
1904	  FAR struct sg2000_eth_priv_s *priv = &g_eth_priv;
1905	  FAR struct netdev_lowerhalf_s *dev = &priv->dev;
1906	  int ret;
1907	
1908	  if (g_eth_initialized)
1909	    {
1910	      ninfo("SG2000 Ethernet driver already initialized\n");
1911	      return OK;
1912	    }
1913	
1914	  memset(priv, 0, sizeof(*priv));
1915	  priv->gmac_base = SG2000_GMAC_BASE;
1916	  priv->phy_base = SG2000_EPHY_BASE;
1917	  priv->phy_top = SG2000_EPHY_TOP;
1918	
1919	  /* Set a test MAC address (should be replaced with eFuse/OTP value) */
1920	
1921	  priv->mac_addr[0] = 0x02;
1922	  priv->mac_addr[1] = 0x00;
1923	  priv->mac_addr[2] = 0x00;
1924	  priv->mac_addr[3] = 0x00;
1925	  priv->mac_addr[4] = 0x00;
1926	  priv->mac_addr[5] = 0x01;
1927	
1928	  memcpy(dev->netdev.d_mac.ether.ether_addr_octet, priv->mac_addr,
1929	         IFHWADDRLEN);
1930	
1931	  dev->quota[NETPKT_TX] = TX_RING_SIZE / 2;
1932	  dev->quota[NETPKT_RX] = RX_RING_SIZE / 2;
1933	  dev->ops              = &g_ops;
1934	
1935	  priv->irq = SG2000_IRQ_GMAC;
1936	
1937	  ret = netdev_lower_register(dev, NET_LL_ETHERNET);
1938	  if (ret < 0)
1939	    {
1940	      nerr("ERROR: netdev_lower_register failed: %d\n", ret);
1941	      return ret;
1942	    }
1943	
1944	  netdev_lower_carrier_off(dev);
1945	  g_eth_initialized = true;
1946	  ninfo("SG2000 Ethernet driver registered as eth0 (lowerhalf)\n");
1947	
1948	  gmac_clock_enable();
1949	
1950	  ret = irq_attach(priv->irq, sg2000_eth_isr, priv);
1951	  if (ret < 0)
1952	    {
1953	      nerr("ERROR: irq_attach failed: %d\n", ret);
1954	      return OK;
1955	    }
1956	
1957	  up_enable_irq(priv->irq);
1958	  ninfo("IRQ %d enabled\n", priv->irq);
1959	
1960	  return OK;
1961	}
