43	/****************************************************************************
44	 * Name: up_irqinitialize
45	 ****************************************************************************/
46	
47	void up_irqinitialize(void)
48	{
49	  uintptr_t claim;
50	
51	  /* Disable S-Mode interrupts */
52	
53	  up_irq_save();
54	
55	  /* Attach the common interrupt handler */
56	
57	  riscv_exception_attach();
58	
59	  /* Disable all global interrupts */
60	
61	  putreg32(0x0, SG2000_PLIC_ENABLE1);
62	  putreg32(0x0, SG2000_PLIC_ENABLE2);
63	
64	  /* Clear pendings in PLIC */
65	
66	  claim = getreg32(SG2000_PLIC_CLAIM);
67	  putreg32(claim, SG2000_PLIC_CLAIM);
68	
69	  /* Colorize the interrupt stack for debug purposes */
70	
71	#if defined(CONFIG_STACK_COLORATION) && CONFIG_ARCH_INTERRUPTSTACK > 15
72	  size_t intstack_size = (CONFIG_ARCH_INTERRUPTSTACK & ~15);
73	  riscv_stack_color(g_intstackalloc, intstack_size);
74	#endif
75	
76	  /* Set priority for all global interrupts to 1 (lowest) */
77	
78	  int id;
79	
80	  for (id = 1; id <= NR_IRQS; id++)
81	    {
82	      putreg32(1, (uintptr_t)(SG2000_PLIC_PRIORITY + 4 * id));
83	    }
84	
85	  /* Set irq threshold to 0 (permits all global interrupts) */
86	
87	  putreg32(0, SG2000_PLIC_THRESHOLD);
88	
89	#ifdef CONFIG_SMP
90	  /* Clear IPI for CPU0 */
91	
92	  riscv_ipi_clear(0);
93	
94	  up_enable_irq(RISCV_IRQ_SOFT);
95	#endif
96	
97	#ifndef CONFIG_SUPPRESS_INTERRUPTS
98	
99	  /* And finally, enable interrupts */
100	
101	  riscv_color_intstack();
102	  up_irq_enable();
103	#endif
104	}
