106	/****************************************************************************
107	 * Name: up_disable_irq
108	 *
109	 * Description:
110	 *   Disable the IRQ specified by 'irq'
111	 *
112	 ****************************************************************************/
113	
114	void up_disable_irq(int irq)
115	{
116	  int extirq;
117	
118	  if (irq == RISCV_IRQ_SOFT)
119	    {
120	      /* Read sstatus & clear software interrupt enable in sie */
121	
122	      CLEAR_CSR(CSR_IE, IE_SIE);
123	    }
124	  else if (irq == RISCV_IRQ_TIMER)
125	    {
126	      /* Read sstatus & clear timer interrupt enable in sie */
127	
128	      CLEAR_CSR(CSR_IE, IE_TIE);
129	    }
130	  else if (irq > RISCV_IRQ_EXT)
131	    {
132	      extirq = irq - RISCV_IRQ_EXT;
133	
134	      /* Clear enable bit for the irq */
135	
136	      if (0 <= extirq && extirq <= 63)
137	        {
138	          modifyreg32(SG2000_PLIC_ENABLE1 + (4 * (extirq / 32)),
139	                      1 << (extirq % 32), 0);
140	        }
141	      else
142	        {
143	          PANIC();
144	        }
145	    }
146	}
147	
148	/****************************************************************************
149	 * Name: up_enable_irq
150	 *
151	 * Description:
152	 *   Enable the IRQ specified by 'irq'
153	 *
154	 ****************************************************************************/
155	
156	void up_enable_irq(int irq)
157	{
158	  int extirq;
159	
160	  if (irq == RISCV_IRQ_SOFT)
161	    {
162	      /* Read sstatus & set software interrupt enable in sie */
163	
164	      SET_CSR(CSR_IE, IE_SIE);
165	    }
166	  else if (irq == RISCV_IRQ_TIMER)
167	    {
168	      /* Read sstatus & set timer interrupt enable in sie */
169	
170	      SET_CSR(CSR_IE, IE_TIE);
171	    }
172	  else if (irq > RISCV_IRQ_EXT)
173	    {
174	      extirq = irq - RISCV_IRQ_EXT;
175	
176	      /* Set enable bit for the irq */
177	
178	      if (0 <= extirq && extirq <= 63)
179	        {
180	          modifyreg32(SG2000_PLIC_ENABLE1 + (4 * (extirq / 32)),
181	                      0, 1 << (extirq % 32));
182	        }
183	      else
184	        {
185	          PANIC();
186	        }
187	    }
188	}
189	
190	irqstate_t up_irq_enable(void)
191	{
192	  irqstate_t oldstat;
193	
194	  /* Enable external interrupts (sie) */
195	
196	  SET_CSR(CSR_IE, IE_EIE);
197	
198	  /* Read and enable global interrupts (sie) in sstatus */
199	
200	  oldstat = READ_AND_SET_CSR(CSR_STATUS, STATUS_IE);
201	
202	  return oldstat;
203	}
