/****************************************************************************
 * Name: c906_invalidate_dcache_line
 *
 * Description:
 *   Invalidate (作废) the D-cache line containing the virtual address.
 *   Force the next CPU read of this address to fetch from DDR.
 *   Use after DMA has written to a buffer that the CPU is about to read.
 *
 *   T-Head C906 custom instruction: DCACHE.IVA (0x02b5000b)
 *   Address passed via a0 (x10) register.
 *
 ****************************************************************************/

static inline void c906_invalidate_dcache_line(uintptr_t addr)
{
  register uintptr_t a0 asm("a0") = addr;

  __asm__ volatile (".long 0x02b5000b\n" : : "r"(a0) : "memory");
}

/****************************************************************************
 * Name: c906_invalidate_dcache_range
 *
 * Description:
 *   Invalidate all D-cache lines overlapping [start, end).
 *   Used after DMA writes, before CPU reads — discards stale cached data
 *   so the CPU sees the fresh DMA-written data from DDR.
 *
 *   SAFER than C906_DCACHE_CIAL() because it only touches the specified
 *   address range instead of the entire D-cache.  CIALL writes back ALL
 *   dirty lines first, which can corrupt DMA data if a cache line
 *   covering a DMA-written buffer was still dirty from a prior CPU write.
 *
 ****************************************************************************/

static inline void c906_invalidate_dcache_range(uintptr_t start,
                                                 uintptr_t end)
{
  uintptr_t addr = start & ~(C906_DCACHE_LINE_SIZE - 1);

  while (addr < end)
    {
      c906_invalidate_dcache_line(addr);
      addr += C906_DCACHE_LINE_SIZE;
    }
}

/****************************************************************************
 * Name: c906_dma_invalidate_after_rx
 *
 * Description:
 *   After DMA writes into rx_buf and rx_desc, invalidate their cache
 *   lines so the CPU sees the fresh data.  Sync first, then invalidate
 *   the exact buffer + descriptor ranges only.
 *
 ****************************************************************************/

static inline void c906_dma_invalidate_after_rx(uintptr_t buf, int buf_len,
                                                 uintptr_t desc, int desc_len)
{
  C906_SYNC_S();
  c906_invalidate_dcache_range(buf, buf + buf_len);
  c906_invalidate_dcache_range(desc, desc + desc_len);
}

